// ---- Level 1 verifier (app/lib/offline_verify.mjs, unchanged) ----
/**
 * Verify without TET, Level 1: "this key signed this hash", fully offline, no chain needed.
 *
 * This module is inlined, unchanged, into the standalone verifier (public/verify/tet-verify.html)
 * and the CLI (public/verify/tet-verify.mjs), so it imports nothing: SHA-256 and Ed25519 come from
 * the platform's own WebCrypto, and ML-DSA-44 from an injected function (the inlined WASM).
 * It mirrors `verify_anything.mjs` `verifyEnvelope` check for check (tet-core `agent.rs`), and
 * scripts/offline_verify_guard.mjs runs both on the same valid and tampered records: they must agree.
 *
 * What a pass proves: the two keys named in the record signed that SHA-256 (and, if a file is given,
 * that the file hashes to it), bound to the named chain. What it doesn't prove: who holds the keys,
 * that the file's content is true, or when it was signed (that needs Level 2: a chain copy).
 */

const PAE_DOMAIN = "tet agent payload v1";
const HASH_PAYLOAD_TYPE = "application/vnd.tet.sha256";
const ED_PREFIX = "tet-ed25519:";
const ML_PREFIX = "tet-mldsa44:";
const MLDSA44_PUB = 1312;
const MLDSA44_SIG = 2420;
const ED_SIG = 64;
const CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

const enc = new TextEncoder();
const utf8 = (s) => enc.encode(s);
const concat = (parts) => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let i = 0;
  for (const p of parts) {
    out.set(p, i);
    i += p.length;
  }
  return out;
};
const hex = (b) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
const hexToBytes = (h) => Uint8Array.from(h.match(/../g) ?? [], (x) => parseInt(x, 16));
function b64ToBytes(s) {
  const bin = atob(String(s).trim());
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}
const is64hex = (s) => typeof s === "string" && /^[0-9a-f]{64}$/.test(s);
const same = (a, b) => a.length === b.length && a.every((x, i) => x === b[i]);
const no = (reason) => ({ ok: false, reason });

async function sha256(bytes) {
  return new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
}

async function ed25519Verify(pubHex, sigB64, msg) {
  try {
    const sig = b64ToBytes(sigB64);
    if (sig.length !== ED_SIG) return false;
    const key = await crypto.subtle.importKey("raw", hexToBytes(pubHex), { name: "Ed25519" }, false, ["verify"]);
    return await crypto.subtle.verify({ name: "Ed25519" }, key, sig, msg);
  } catch {
    return false;
  }
}

/** Does this platform's WebCrypto have Ed25519? (Browsers since 2024–25, Node 20+.) */
async function hasEd25519() {
  try {
    await crypto.subtle.importKey("raw", new Uint8Array(32), { name: "Ed25519" }, false, ["verify"]);
    return true;
  } catch {
    return false;
  }
}

/** The bytes a key signs (tet-core `agent_payload_auth_message_bytes`): PAE, chain-bound. */
function payloadAuthMessageBytes(chain, payloadType, payload) {
  const fields = [utf8(chain.chainId), utf8(chain.genesisHash), utf8(String(payloadType).trim()), payload];
  const parts = [utf8(PAE_DOMAIN), utf8(" ")];
  for (const f of fields) parts.push(utf8(String(f.length)), utf8(" "), f, utf8(" "));
  return concat(parts);
}

/** `TET-XXXX-XXXX`: 40 bits of SHA-256(record bytes), Crockford base32 (`proof_code.ts`). */
async function proofCode(recordBytes) {
  const h = await sha256(recordBytes);
  let bits = 0n;
  for (const b of h.slice(0, 5)) bits = (bits << 8n) | BigInt(b);
  let out = "";
  for (let i = 7; i >= 0; i--) out += CROCKFORD[Number((bits >> BigInt(i * 5)) & 31n)];
  return `TET-${out.slice(0, 4)}-${out.slice(4)}`;
}

/**
 * Level 1. `recordBytes`: the .sig.json / .record.json exactly as saved. `file` (optional): the file
 * it marks; without it, only a hash-only record can be checked (it then says which SHA-256 was
 * signed). `chain`: { chainId, genesisHash } the signature is bound to.
 *
 * @returns {Promise<{ ok: true, signer: string, mldsaKeyId: string, payloadType: string, signedSha256: string | null, fileMatches: boolean | null, proofCode: string }
 *                   | { ok: false, reason: string }>}
 */
async function verifyRecordOffline({ recordBytes, file, chain, mldsa44Verify }) {
  let e;
  try {
    e = JSON.parse(new TextDecoder().decode(recordBytes));
  } catch {
    return no("the record is not JSON");
  }
  if (!e || typeof e !== "object" || Array.isArray(e)) return no("the record is not a JSON object");
  if (!e.tet || e.tet.v !== 1) return no("unsupported envelope version");
  if (e.tet.pae !== PAE_DOMAIN) return no(`unknown pre-image encoding ${JSON.stringify(e.tet.pae)}`);
  for (const k of Object.keys(e)) if (!["payloadType", "payload", "signatures", "tet"].includes(k)) return no(`unexpected field ${JSON.stringify(k)}`);
  for (const k of Object.keys(e.tet)) {
    if (!["v", "pae", "agent_ed25519_pubkey_hex", "agent_mldsa44_pubkey_b64"].includes(k)) return no(`unexpected field tet.${k}`);
  }
  if (typeof e.payloadType !== "string" || !e.payloadType.trim()) return no("payloadType is missing");
  if (!Array.isArray(e.signatures) || e.signatures.length !== 2) return no(`expected exactly 2 signatures, got ${e.signatures?.length ?? 0}`);
  const pick = (p) => e.signatures.filter((s) => typeof s?.keyid === "string" && s.keyid.startsWith(p));
  const eds = pick(ED_PREFIX);
  const mls = pick(ML_PREFIX);
  if (eds.length !== 1) return no("missing or duplicated ed25519 signature");
  if (mls.length !== 1) return no("missing or duplicated ml-dsa-44 signature");
  const edHex = String(e.tet.agent_ed25519_pubkey_hex ?? "");
  const mlPub = String(e.tet.agent_mldsa44_pubkey_b64 ?? "").trim();
  if (!is64hex(edHex)) return no("the ed25519 key is not 64 lowercase hex");
  if (eds[0].keyid !== ED_PREFIX + edHex) return no("ed25519 keyid does not match the key it names");
  let payload, mlSig, mlPubBytes;
  try {
    payload = b64ToBytes(e.payload ?? "");
    mlSig = b64ToBytes(mls[0].sig);
    mlPubBytes = b64ToBytes(mlPub);
  } catch {
    return no("envelope is not valid base64");
  }
  const mlKeyId = ML_PREFIX + hex(await sha256(mlPubBytes));
  if (mls[0].keyid !== mlKeyId) return no("ml-dsa-44 keyid does not match the key it names");
  if (mlPubBytes.length !== MLDSA44_PUB) return no("ml-dsa key is not ML-DSA-44");
  if (mlSig.length !== MLDSA44_SIG) return no("ml-dsa signature is not ML-DSA-44");
  const type = e.payloadType.trim();
  let signedSha256 = null;
  let fileMatches = null;
  if (type === HASH_PAYLOAD_TYPE) {
    if (payload.length !== 32) return no("a hash-only signature must carry exactly 32 bytes");
    signedSha256 = hex(payload);
    if (file) {
      fileMatches = same(payload, await sha256(file));
      if (!fileMatches) return no("the file's SHA-256 differs from the one that was signed");
    }
  } else {
    if (!file) return no("this record signs its content, not a hash: give the file too");
    fileMatches = same(payload, file);
    if (!fileMatches) return no(`the content differs from what was signed (signed ${payload.length} bytes, given ${file.length})`);
  }
  const msg = payloadAuthMessageBytes(chain, e.payloadType, payload);
  if (!(await ed25519Verify(edHex, eds[0].sig, msg))) return no("ed25519 signature does not verify (on this chain binding)");
  if (!(await mldsa44Verify(mlPub, String(mls[0].sig).trim(), msg))) return no("ml-dsa-44 signature does not verify (on this chain binding)");
  return { ok: true, signer: edHex, mldsaKeyId: mlKeyId, payloadType: type, signedSha256, fileMatches, proofCode: await proofCode(recordBytes) };
}

// ---- Level 2 verifier (app/lib/chain_verify.mjs, unchanged) ----
// "Verify without TET", Level 2: is a stamp in a block, and is that block in a chain copy that holds
// together? Pure and offline: the crypto comes in as functions (sha256, ed25519Verify,
// mldsa44Verify), so the same code runs in the offline verifier, the CLI and the guard.
//
// The input is a chain export (scripts/chain_export.mjs): blocks from the stamp's height up, as
// GET /explorer/block/:height gives them — the header fields a block id is computed from, and each
// transaction's canonical JSON as a string (the exact bytes its hash and signatures cover).
//
// What it proves, and what it doesn't: that the export is consistent with itself (each block id
// recomputes, each block names the one before it, the stamp's transaction is signed by its sender
// and listed in its block). Not that this is THE chain: until blocks carry producer signatures
// (Phase 1), anyone can make a consistent copy. Compare the tip's block id with what other nodes
// report.

const EXPORT_KIND = "tet-chain-export";
const ZERO_PARENT = "0x" + "0".repeat(64);
const cvEnc = new TextEncoder();
const hexOf = (b) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
const le64 = (n) => {
  const b = new Uint8Array(8);
  let v = BigInt(n);
  for (let i = 0; i < 8; i++) {
    b[i] = Number(v & 0xffn);
    v >>= 8n;
  }
  return b;
};
const cvConcat = (...parts) => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let o = 0;
  for (const p of parts) {
    out.set(p, o);
    o += p.length;
  }
  return out;
};

/** tet-core `consensus::block_id_for_block`. */
async function blockIdOf(b, sha256) {
  const parent = b.parent_block_id && b.parent_block_id.trim() ? b.parent_block_id : ZERO_PARENT;
  const bytes = cvConcat(
    cvEnc.encode("TET_BLOCK_ID_V2|"),
    le64(b.height),
    cvEnc.encode(`|parent=${parent}|state=${b.state_root}|txs=${b.tx_hashes.join(",")}|producer=${b.producer_id}`),
  );
  return "0x" + hexOf(await sha256(bytes));
}

/** The bytes a (generic) transaction's hash and signatures cover: tet-core `tx_v1_auth_message_bytes`. */
function txPreimage(chain, t) {
  return cvEnc.encode(`tet tx v1|chain_id=${chain.chainId}|genesis_hash=${chain.genesisHash}|mldsa=${String(t.mldsa_pubkey_b64).trim()}|tx=${t.tx_json}`);
}

/**
 * Check a chain export, and (optionally) that a stamp is in it.
 * @param {{ exported: any, chain: { chainId: string, genesisHash: string }, stamp?: { txHash: string, fileId: string },
 *           sha256: (b: Uint8Array) => Promise<Uint8Array>, ed25519Verify: Function, mldsa44Verify: Function }} o
 * @returns {Promise<{ ok: true, from: number, tip: number, tipBlockId: string, stamp: null | { height: number, confirmations: number } }
 *                 | { ok: false, reason: string }>}
 */
async function verifyChainExport(o) {
  const e = o.exported;
  if (!e || e.v !== 1 || e.kind !== EXPORT_KIND || !Array.isArray(e.blocks) || !e.blocks.length) return { ok: false, reason: "not a TET chain export" };
  if (e.chain?.chainId !== o.chain.chainId || String(e.chain?.genesisHash).toLowerCase() !== String(o.chain.genesisHash).toLowerCase()) {
    return { ok: false, reason: "the export is from another chain" };
  }
  let prev = null;
  let found = null;
  for (const b of e.blocks) {
    if ((await blockIdOf(b, o.sha256)) !== b.block_id) return { ok: false, reason: `block ${b.height}: its id doesn't match its contents` };
    if (prev && (b.height !== prev.height + 1 || b.parent_block_id !== prev.block_id)) return { ok: false, reason: `block ${b.height} doesn't follow block ${prev.height}` };
    if (o.stamp && !found) {
      const want = o.stamp.txHash.toLowerCase().replace(/^0x/, "");
      const i = b.tx_hashes.findIndex((h) => h.toLowerCase().replace(/^0x/, "") === want);
      if (i >= 0) {
        const t = b.txs[i];
        const pre = txPreimage(o.chain, t);
        if ("0x" + hexOf(await o.sha256(pre)) !== b.tx_hashes[i]) return { ok: false, reason: "the stamp's transaction doesn't match its hash" };
        let tx;
        try {
          tx = JSON.parse(t.tx_json);
        } catch {
          return { ok: false, reason: "the stamp's transaction isn't readable" };
        }
        if (tx.kind !== "file_fee") return { ok: false, reason: "the transaction is not a file fee" };
        if (String(tx.file_id).toLowerCase() !== o.stamp.fileId.toLowerCase()) return { ok: false, reason: "the transaction stamps a different file" };
        if (String(tx.from_wallet).toLowerCase() !== String(t.ed25519_pubkey_hex).toLowerCase()) return { ok: false, reason: "the transaction isn't signed by its sender" };
        const ed = await o.ed25519Verify(String(t.ed25519_pubkey_hex).toLowerCase(), t.ed25519_sig_b64, pre);
        const pq = await o.mldsa44Verify(t.mldsa_pubkey_b64, t.mldsa_sig_b64, pre);
        if (!ed || !pq) return { ok: false, reason: "the transaction's signatures don't verify" };
        found = b.height;
      }
    }
    prev = b;
  }
  if (o.stamp && found === null) return { ok: false, reason: "the stamp's transaction isn't in this export" };
  const tip = e.blocks[e.blocks.length - 1];
  return { ok: true, from: e.blocks[0].height, tip: tip.height, tipBlockId: tip.block_id, stamp: found === null ? null : { height: found, confirmations: tip.height - found } };
}

/** A stamp's file id (tet-network/ui sign_anything.ts `stampFileId`): the .sig.json's SHA-256, first 16 bytes, as a UUID. */
async function stampFileIdOf(sigBytes, sha256) {
  const h = hexOf((await sha256(sigBytes)).slice(0, 16));
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20, 32)}`;
}

const KNOWN = {"chains":[{"name":"TET public testnet","chainId":"tet-local-dev","genesisHash":"0x9d6ccb1354b31419ade378aef68de58e854938df795b69cf76777e3483efbb36"}],"publisher":"e93a3597f03a8ee4621d8c7340d37fe871875f8dedbc5ec9e139293d0af847bd"};

const args = process.argv.slice(2);
const ci = args.indexOf("--chain");
const chain = ci >= 0 ? { chainId: args[ci + 1], genesisHash: String(args[ci + 2] ?? "").toLowerCase() } : KNOWN.chains[0];
const firstFlag = args.findIndex((a) => a.startsWith("--"));
const pos = firstFlag >= 0 ? args.slice(0, firstFlag) : args;
if (!pos[0]) {
  console.log("usage: node tet-verify.mjs <record.json> [file] [--chain <chainId> <genesisHash>] [--chain-export <export.json> --stamp <.stamp.json>]");
  process.exit(2);
}
const r = await verifyRecordOffline({ recordBytes: new Uint8Array(readFileSync(pos[0])), file: pos[1] ? new Uint8Array(readFileSync(pos[1])) : null, chain, mldsa44Verify });
if (!r.ok) {
  console.log("DOES NOT VERIFY: " + r.reason);
  process.exit(1);
}
console.log("VERIFIED (offline, Level 1) on " + chain.chainId);
console.log("signer ed25519  " + r.signer + (r.signer === KNOWN.publisher ? "  (TET's publisher ID)" : ""));
console.log("ml-dsa-44 key   " + r.mldsaKeyId);
if (r.signedSha256) console.log("signed sha256   " + r.signedSha256);
console.log("file matches    " + (r.fileMatches === null ? "(no file given)" : r.fileMatches));
console.log("proof code      " + r.proofCode);
// Level 2: --chain-export <file> --stamp <.stamp.json>: the stamp's transaction in a block of a
// chain copy that holds together (not proof that it is the chain everyone sees).
const ei = args.indexOf("--chain-export"), si = args.indexOf("--stamp");
if (ei >= 0 && si >= 0) {
  const exported = JSON.parse(readFileSync(args[ei + 1], "utf8"));
  const receipt = JSON.parse(readFileSync(args[si + 1], "utf8"));
  const fileId = await stampFileIdOf(new Uint8Array(readFileSync(pos[0])), sha256);
  if (receipt.file_id && String(receipt.file_id).toLowerCase() !== fileId) {
    console.log("STAMP: the receipt is for another file");
    process.exit(1);
  }
  const l2 = await verifyChainExport({ exported, chain, stamp: { txHash: String(receipt.tx_hash ?? ""), fileId }, sha256, ed25519Verify, mldsa44Verify });
  if (!l2.ok) {
    console.log("STAMP DOES NOT VERIFY: " + l2.reason);
    process.exit(1);
  }
  console.log("STAMP (Level 2)  in block " + l2.stamp.height + ", " + l2.stamp.confirmations + " blocks under the copy's tip " + l2.tipBlockId);
  console.log("                 the copy is consistent with itself; compare its tip with other nodes");
}
